const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const MAX_API_UPLOADS_PER_DAY = 6;
const MIN_SPACING_MINUTES = 45;
const EXCESS_THROTTLE_MS = 2 * 3600 * 1000;
const SCRAPER_LOCK_EXPIRY_SEC = 1500;
const SCORE_TIE_BAND = 0.4;

const inJson = ($input.first() && $input.first().json) ? $input.first().json : {};
const OUTPUTS_DIR = String(inJson._test_outputs_dir || inJson.outputs_dir || '/files/outputs');
const INPUTS_DIR = String(inJson._test_inputs_dir || inJson.inputs_dir || '/files/inputs');
const QUOTA_STATE_PATH = String(inJson._test_quota_state_path || inJson.quota_state_path || '/files/temp/yt_quota_state.json');
const EXCESS_STATE_PATH = String(inJson._test_excess_state_path || inJson.excess_state_path || '/files/temp/yt_excess_alert_state.json');
const SCRAPER_LOCK_PATH = String(inJson._test_scraper_lock_path || inJson.scraper_lock_path || '/files/temp/live_chunk_scraper.lock');
const HISTORY_PATH = String(inJson._test_history_path || inJson.history_path || path.join(OUTPUTS_DIR, 'published_history.json'));
const NOW_MS = (typeof inJson._test_now_ms === 'number' && Number.isFinite(inJson._test_now_ms))
  ? inJson._test_now_ms
  : Date.now();

function safeReadJson(filePath, fallback) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    const raw = fs.readFileSync(filePath, 'utf8');
    if (!raw || !raw.trim()) return fallback;
    return JSON.parse(raw);
  } catch (e) {
    return fallback;
  }
}

function safeWriteJson(filePath, obj) {
  try {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(filePath, JSON.stringify(obj, null, 2), 'utf8');
  } catch (e) {}
}

// Africa/Algiers daily boundary at 08:00 AM: subtract 8 hours then take YYYY-MM-DD in Africa/Algiers.
function getAlgiersQuotaDay(epochMs) {
  const shifted = new Date(Number(epochMs) - 8 * 3600 * 1000);
  try {
    const parts = new Intl.DateTimeFormat('en-CA', {
      timeZone: 'Africa/Algiers',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(shifted);
    const map = {};
    for (const p of parts) map[p.type] = p.value;
    if (map.year && map.month && map.day) return `${map.year}-${map.month}-${map.day}`;
  } catch (e) {}
  // Africa/Algiers is fixed UTC+1 (no DST)
  const utcPlus1 = new Date(shifted.getTime() + 3600 * 1000);
  return utcPlus1.toISOString().slice(0, 10);
}

function safeSlice(str, maxLen) {
  const s = String(str || '');
  if (s.length <= maxLen) return s;
  let cut = s.slice(0, maxLen);
  const lastCode = cut.charCodeAt(cut.length - 1);
  if (lastCode >= 0xD800 && lastCode <= 0xDBFF) {
    cut = cut.slice(0, -1);
  }
  return cut;
}

function sanitizeTitleText(str) {
  return String(str || '')
    .replace(/[<>]/g, ' ')
    .replace(/[\x00-\x1F\x7F]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function sanitizeDescText(str) {
  return String(str || '')
    .replace(/[<>]/g, '')
    .replace(/[\x00-\x09\x0B-\x1F\x7F]/g, '')
    .trim();
}

function clampYouTubeTitle(rawTitle, fallbackCaption) {
  const MAX_LEN = 95;
  let base = sanitizeTitleText(rawTitle) || sanitizeTitleText(fallbackCaption) || 'INSANE GAMING MOMENT';

  const hasShorts = /#shorts\b/i.test(base);
  if (hasShorts) {
    if (base.length <= MAX_LEN) return base;
    // Strip trailing #Shorts, clamp core, re-append #Shorts
    const core = base.replace(/\s*#shorts\b/gi, '').replace(/\s+/g, ' ').trim();
    const suffix = ' #Shorts';
    const maxCore = MAX_LEN - suffix.length;
    const trimmedCore = safeSlice(core, maxCore).replace(/\s+\S*$/, (m) => (core.length > maxCore && m.length < 15 ? '' : m)).trim() || safeSlice(core, maxCore).trim();
    return safeSlice((trimmedCore || 'INSANE GAMING MOMENT') + suffix, MAX_LEN);
  }

  const suffix = ' #Shorts';
  const maxCore = MAX_LEN - suffix.length;
  if (base.length <= maxCore) {
    return base + suffix;
  }
  let trimmed = safeSlice(base, maxCore).trim();
  if (trimmed.includes(' ') && trimmed.length > 20) {
    const wordBound = trimmed.replace(/\s+\S*$/, '').trim();
    if (wordBound.length >= 12) trimmed = wordBound;
  }
  return safeSlice((trimmed || 'INSANE GAMING MOMENT') + suffix, MAX_LEN);
}

function buildYouTubeDescription(meta, title, creatorCredit, baitQ) {
  if (meta.youtube_description && String(meta.youtube_description).trim()) {
    return sanitizeDescText(meta.youtube_description);
  }
  if (meta.platform_copy && meta.platform_copy.youtube_shorts && String(meta.platform_copy.youtube_shorts).trim()) {
    return sanitizeDescText(meta.platform_copy.youtube_shorts);
  }
  const hook = String(meta.viral_caption || title || 'INSANE MOMENT').trim();
  const valueNote = String(meta.visual_value_note || '').trim();
  const summary = String(meta.short_description || meta.global_summary || 'Epic gaming moment!').trim();
  const game = String(meta.game || 'Gaming').trim();
  const gameTag = '#' + (game.replace(/[^a-zA-Z0-9]/g, '') || 'Gaming');
  const lines = [hook];
  if (valueNote) lines.push('', valueNote);
  if (baitQ) lines.push('', baitQ);
  if (creatorCredit) lines.push('', creatorCredit);
  if (summary) lines.push('', summary);
  lines.push('', `#Shorts #Gaming #Viral #GamingClips ${gameTag}`);
  return sanitizeDescText(lines.join('\n'));
}

function sha256FileSync(filePath) {
  const hash = crypto.createHash('sha256');
  const fd = fs.openSync(filePath, 'r');
  try {
    const buf = Buffer.allocUnsafe(1024 * 1024);
    let bytesRead = 0;
    while ((bytesRead = fs.readSync(fd, buf, 0, buf.length, null)) > 0) {
      hash.update(buf.subarray(0, bytesRead));
    }
  } finally {
    fs.closeSync(fd);
  }
  return hash.digest('hex');
}

function escapeHtml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function isProtectedNonSidecar(fileName, fullPath) {
  if (
    fileName === 'published_history.json' ||
    fileName === 'scoreboard.csv' ||
    fileName === 'player_blacklist.json' ||
    fileName === 'active_workflow.json' ||
    fileName === 'live_wf.json' ||
    fileName === 'updated_workflow.json' ||
    fileName === 'workflow_generator.json' ||
    fileName === 'edl_test.json' ||
    fileName === 'enriched_test.json'
  ) {
    return true;
  }
  if (/^(ANTIGRAVITY_|whisper_|exec_)/i.test(fileName)) return true;
  try {
    const raw = fs.readFileSync(fullPath, 'utf8');
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return true;
    if (parsed && typeof parsed === 'object') {
      if (Array.isArray(parsed.nodes) && parsed.connections) return true;
      if (Array.isArray(parsed.scenarios)) return true;
    }
  } catch (e) {
    // Broken JSON without matching .mp4 is treated as orphan sidecar
  }
  return false;
}

// 1. Scan /files/outputs & perform orphan .json cleanup
const orphansDeleted = [];
let dirEntries = [];
if (fs.existsSync(OUTPUTS_DIR)) {
  dirEntries = fs.readdirSync(OUTPUTS_DIR);
}

const mp4Set = new Set(
  dirEntries.filter((f) => {
    if (!/\.mp4$/i.test(f)) return false;
    if (/\.(tmp|processing)\.mp4$/i.test(f) || f.startsWith('.')) return false;
    try {
      return fs.statSync(path.join(OUTPUTS_DIR, f)).isFile();
    } catch (e) {
      return false;
    }
  })
);

for (const fileName of dirEntries) {
  if (!/\.json$/i.test(fileName) || fileName.startsWith('.')) continue;
  const fullPath = path.join(OUTPUTS_DIR, fileName);
  let isFile = false;
  try { isFile = fs.statSync(fullPath).isFile(); } catch (e) {}
  if (!isFile) continue;

  const expectedMp4 = fileName.slice(0, -5) + '.mp4';
  if (!mp4Set.has(expectedMp4)) {
    if (!isProtectedNonSidecar(fileName, fullPath)) {
      try {
        fs.unlinkSync(fullPath);
        orphansDeleted.push(fileName);
      } catch (e) {}
    }
  }
}

// 2. Load published_history.json for filename + SHA-256 deduplication
const rawHistory = safeReadJson(HISTORY_PATH, []);
const historyArr = Array.isArray(rawHistory)
  ? rawHistory
  : (rawHistory && Array.isArray(rawHistory.history) ? rawHistory.history : []);
const publishedFilenames = new Set();
const publishedHashes = new Set();
for (const entry of historyArr) {
  if (!entry || typeof entry !== 'object') continue;
  if (entry.filename) publishedFilenames.add(String(entry.filename));
  if (entry.sha256) publishedHashes.add(String(entry.sha256).toLowerCase());
}

// 3. Build ranked clip queue
const rawClips = [];
for (const mp4Name of mp4Set) {
  const mp4Path = path.join(OUTPUTS_DIR, mp4Name);
  let stat;
  try {
    stat = fs.statSync(mp4Path);
  } catch (e) {
    continue;
  }
  const sha256 = sha256FileSync(mp4Path).toLowerCase();
  if (publishedFilenames.has(mp4Name) || publishedHashes.has(sha256)) {
    continue;
  }

  const stem = mp4Name.slice(0, -4);
  const jsonPath = path.join(OUTPUTS_DIR, stem + '.json');
  const hasSidecar = fs.existsSync(jsonPath);
  const meta = hasSidecar ? safeReadJson(jsonPath, {}) : {};
  if (hasSidecar && meta && meta.has_webcam === false) {
    continue;
  }

  const parsedScore = Number(meta.virality_score ?? meta.viral_score);
  const rawScore = Number.isFinite(parsedScore) ? parsedScore : 5.0;
  const roundedScore = Math.round(rawScore * 10) / 10;

  let createdAtEpoch = Number(meta.created_at_epoch);
  if (!Number.isFinite(createdAtEpoch) || createdAtEpoch <= 0) {
    const isoMs = meta.created_at_iso ? Date.parse(meta.created_at_iso) : NaN;
    createdAtEpoch = Number.isFinite(isoMs) ? isoMs : stat.mtimeMs;
  }

  const viralCaption = String(meta.viral_caption || stem).trim();
  const narrativeArchetype = String(meta.narrative_archetype || meta.archetype || meta.theme || 'GAMING_HIGHLIGHT').trim();
  const streamerHandle = String(meta.streamer_handle || '').replace(/^@/, '').trim();
  const creatorCredit = String(meta.creator_credit || (streamerHandle ? ('🎥 @' + streamerHandle) : '')).trim();
  const commentBaitQuestion = String(meta.comment_bait_question || '').trim();
  const youtubeTitle = clampYouTubeTitle(meta.youtube_title, viralCaption);
  const youtubeDescription = buildYouTubeDescription(meta, stem, creatorCredit, commentBaitQuestion);

  rawClips.push({
    filename: mp4Name,
    stem,
    mp4_path: mp4Path,
    json_path: hasSidecar ? jsonPath : null,
    has_sidecar: hasSidecar,
    sha256,
    file_size_bytes: stat.size,
    virality_score: roundedScore,
    created_at_epoch: createdAtEpoch,
    viral_caption: viralCaption,
    narrative_archetype: narrativeArchetype,
    creator_credit: creatorCredit,
    comment_bait_question: commentBaitQuestion,
    youtube_title: youtubeTitle,
    youtube_description: youtubeDescription,
  });
}

// Transitive tolerance clustering sort:
// Primary: virality_score (rounded to 1 decimal) descending.
// Ties or differences <= 0.4 within a descending tier are broken by created_at_epoch descending (newest first).
rawClips.sort((a, b) =>
  (b.virality_score - a.virality_score) ||
  (b.created_at_epoch - a.created_at_epoch) ||
  a.filename.localeCompare(b.filename)
);

const rankedQueue = [];
let idx = 0;
while (idx < rawClips.length) {
  const anchorScore = rawClips[idx].virality_score;
  const tier = [rawClips[idx]];
  idx++;
  while (idx < rawClips.length && Math.round((anchorScore - rawClips[idx].virality_score) * 10) / 10 <= SCORE_TIE_BAND) {
    tier.push(rawClips[idx]);
    idx++;
  }
  tier.sort((a, b) =>
    (b.created_at_epoch - a.created_at_epoch) ||
    (b.virality_score - a.virality_score) ||
    a.filename.localeCompare(b.filename)
  );
  for (const item of tier) rankedQueue.push(item);
}

// 4. Quota state & 08:00 AM Africa/Algiers daily boundary reset
const currentQuotaDay = getAlgiersQuotaDay(NOW_MS);
const rawQuota = safeReadJson(QUOTA_STATE_PATH, {});
let uploadsToday = Math.max(0, Number(rawQuota.uploads_today) || 0);
const lastUploadEpoch = (typeof rawQuota.last_upload_epoch === 'number' && Number.isFinite(rawQuota.last_upload_epoch) && rawQuota.last_upload_epoch > 0)
  ? rawQuota.last_upload_epoch
  : 0;
const savedQuotaDay = rawQuota.quota_day
  ? String(rawQuota.quota_day)
  : (lastUploadEpoch > 0 ? getAlgiersQuotaDay(lastUploadEpoch) : currentQuotaDay);

if (savedQuotaDay !== currentQuotaDay) {
  uploadsToday = 0;
  safeWriteJson(QUOTA_STATE_PATH, {
    uploads_today: 0,
    last_upload_epoch: lastUploadEpoch,
    quota_day: currentQuotaDay,
    updated_at_iso: new Date(NOW_MS).toISOString(),
  });
}

const slotsRemaining = Math.max(0, MAX_API_UPLOADS_PER_DAY - uploadsToday);
const minutesSinceLastUpload = lastUploadEpoch > 0
  ? Math.max(0, Number(((NOW_MS - lastUploadEpoch) / 60000).toFixed(2)))
  : null;
const spacingOk = (lastUploadEpoch <= 0) || (minutesSinceLastUpload >= MIN_SPACING_MINUTES);

const queueCount = rankedQueue.length;
const queueEmpty = queueCount === 0;
const canApiPublish = !queueEmpty && slotsRemaining > 0 && spacingOk;
const excessForManual = queueCount > (MAX_API_UPLOADS_PER_DAY - uploadsToday);

// 5. Excess manual alert throttle check (Branch B writes yt_excess_alert_state.json when sending)
const rawExcess = safeReadJson(EXCESS_STATE_PATH, {});
const lastAlertEpoch = (typeof rawExcess.last_alert_epoch === 'number' && Number.isFinite(rawExcess.last_alert_epoch))
  ? rawExcess.last_alert_epoch
  : 0;
const lastAlertCount = (typeof rawExcess.last_count === 'number' && Number.isFinite(rawExcess.last_count))
  ? rawExcess.last_count
  : -1;
const countChanged = queueCount !== lastAlertCount;
const twoHoursElapsed = !lastAlertEpoch || ((NOW_MS - lastAlertEpoch) >= EXCESS_THROTTLE_MS);
const shouldSendExcessEmail = excessForManual && (countChanged || twoHoursElapsed);

// 6. Build excess_clips_list & excess_html_list
const excessSlice = rankedQueue.slice(slotsRemaining);
const excessClipsList = excessSlice.map((clip, i) => ({
  rank: slotsRemaining + i + 1,
  filename: clip.filename,
  mp4_path: clip.mp4_path,
  json_path: clip.json_path,
  sha256: clip.sha256,
  virality_score: clip.virality_score,
  narrative_archetype: clip.narrative_archetype,
  creator_credit: clip.creator_credit || '🎥 @Streamer',
  youtube_title: clip.youtube_title,
  youtube_description: clip.youtube_description,
}));

const excessHtmlList = excessClipsList.length
  ? excessClipsList.map((c) => `
    <div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:10px 0;background:#fafafa;">
      <p style="margin:0 0 6px 0;"><strong>#${c.rank} &bull; ${escapeHtml(c.filename)}</strong> (Score: <strong>${c.virality_score}</strong> | ${escapeHtml(c.narrative_archetype)})</p>
      <p style="margin:4px 0;"><strong>Title (${c.youtube_title.length}/95):</strong> <code>${escapeHtml(c.youtube_title)}</code></p>
      <p style="margin:4px 0;"><strong>Creator Credit:</strong> ${escapeHtml(c.creator_credit)}</p>
      <p style="margin:4px 0;"><strong>Description:</strong></p>
      <pre style="white-space:pre-wrap;background:#fff;border:1px solid #eee;padding:8px;border-radius:4px;font-family:sans-serif;font-size:13px;">${escapeHtml(c.youtube_description)}</pre>
      <p style="margin:4px 0;color:#666;font-size:12px;">Path: <code>${escapeHtml(c.mp4_path)}</code></p>
    </div>`).join('\n')
  : '<p>No excess clips.</p>';

// 7. Check generator processing state (/files/inputs/*.processing.mp4 & /files/temp/live_chunk_scraper.lock)
let processingFiles = [];
try {
  if (fs.existsSync(INPUTS_DIR)) {
    processingFiles = fs.readdirSync(INPUTS_DIR).filter((f) => /\.processing\.mp4$/i.test(f));
  }
} catch (e) {}

let scraperLockActive = false;
try {
  if (fs.existsSync(SCRAPER_LOCK_PATH)) {
    const lockInfo = safeReadJson(SCRAPER_LOCK_PATH, {});
    const startedMs = (Number(lockInfo.started_epoch) > 0)
      ? (Number(lockInfo.started_epoch) * 1000)
      : fs.statSync(SCRAPER_LOCK_PATH).mtimeMs;
    const ageSec = (NOW_MS - startedMs) / 1000;
    const pid = Number(lockInfo.pid) || 0;
    let pidAlive = false;
    if (pid > 0) {
      try {
        if (typeof process !== 'undefined' && typeof process.kill === 'function') {
          process.kill(pid, 0);
          pidAlive = true;
        } else {
          pidAlive = fs.existsSync('/proc/' + pid);
        }
      } catch (ePid) {
        try { pidAlive = fs.existsSync('/proc/' + pid); } catch (eProc) { pidAlive = false; }
      }
    }
    if (ageSec < SCRAPER_LOCK_EXPIRY_SEC && (pidAlive || pid === 0)) {
      scraperLockActive = true;
    }
  }
} catch (e) {}

return [{
  json: {
    queue_empty: queueEmpty,
    can_api_publish: canApiPublish,
    excess_for_manual: excessForManual,
    should_send_excess_email: shouldSendExcessEmail,
    uploads_today: uploadsToday,
    slots_remaining: slotsRemaining,
    minutes_since_last_upload: minutesSinceLastUpload,
    queue_count: queueCount,
    top_clip: rankedQueue.length ? rankedQueue[0] : null,
    excess_clips_list: excessClipsList,
    excess_html_list: excessHtmlList,
    is_scraper_locked: scraperLockActive,
    is_generator_processing: processingFiles.length > 0 || scraperLockActive,
    processing_files: processingFiles,
    orphans_deleted: orphansDeleted,
    quota_day: currentQuotaDay,
    _paths: {
      outputs_dir: OUTPUTS_DIR,
      inputs_dir: INPUTS_DIR,
      quota_state_path: QUOTA_STATE_PATH,
      excess_state_path: EXCESS_STATE_PATH,
      scraper_lock_path: SCRAPER_LOCK_PATH,
      history_path: HISTORY_PATH,
    },
    _now_ms: NOW_MS,
  }
}];

