const fs = require('fs');
const path = require('path');

const item = ($input.first() && $input.first().json) ? $input.first().json : {};
const statePath = (item._paths && item._paths.excess_state_path) || item._test_excess_state_path || '/files/temp/yt_excess_alert_state.json';
const nowMs = (typeof item._now_ms === 'number' && Number.isFinite(item._now_ms)) ? item._now_ms : Date.now();
const count = Number(item.queue_count) || 0;

try {
  const dir = path.dirname(statePath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(statePath, JSON.stringify({
    last_alert_epoch: nowMs,
    last_count: count,
    updated_at_iso: new Date(nowMs).toISOString(),
  }, null, 2), 'utf8');
} catch (e) {}

return [{ json: { ...item } }];

const inItem = $input.first() || {};
let scanData = {};
try {
  scanData = $('Scan & Rank Output Queue').first().json || {};
} catch (e) {
  scanData = inItem.json || {};
}

const topClip = scanData.top_clip || (inItem.json && inItem.json.top_clip);
if (!topClip || !topClip.mp4_path) {
  throw new Error('No top_clip available for YouTube upload.');
}

let binary = inItem.binary;
if (!binary || !binary.data) {
  try {
    binary = $('Read Clip Binary').first().binary;
  } catch (e) {}
}

function safeSlice(str, maxLen) {
  const s = String(str || '');
  if (s.length <= maxLen) return s;
  let cut = s.slice(0, maxLen);
  const lastCode = cut.charCodeAt(cut.length - 1);
  if (lastCode >= 0xD800 && lastCode <= 0xDBFF) cut = cut.slice(0, -1);
  return cut;
}

let title = String(topClip.youtube_title || topClip.viral_caption || 'INSANE GAMING MOMENT')
  .replace(/[<>]/g, ' ')
  .replace(/[\x00-\x1F\x7F]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim() || 'INSANE GAMING MOMENT';
if (title.length > 95) {
  const core = title.replace(/\s*#shorts\b/gi, '').trim() || 'INSANE GAMING MOMENT';
  title = safeSlice(core, 87).trim() + ' #Shorts';
}
if (!/#shorts\b/i.test(title) && title.length <= 87) {
  title = title + ' #Shorts';
}
title = safeSlice(title, 95);

const description = String(topClip.youtube_description || title)
  .replace(/[<>]/g, '')
  .replace(/[\x00-\x09\x0B-\x1F\x7F]/g, '')
  .trim() || title;
const requestBody = {
  snippet: {
    title,
    description,
    categoryId: '20',
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false,
  },
};

return [{
  json: {
    ...scanData,
    top_clip: {
      ...topClip,
      youtube_title: title,
      youtube_description: description,
    },
    youtube_title: title,
    youtube_description: description,
    yt_request_body: requestBody,
  },
  binary,
}];

const resp = ($input.first() && $input.first().json) ? $input.first().json : {};
const headers = resp.headers || {};
let uploadUrl = headers.location || headers.Location || null;
if (!uploadUrl) {
  for (const k of Object.keys(headers)) {
    if (String(k).toLowerCase() === 'location' && headers[k]) {
